import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.2af478d7.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md"}'),d={name:"troubleshooting.md"};function s(n,e,i,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Find a symptom or an exception, learn its cause and apply the fix. Visitors only ever see generic messages; the detail is in your application log.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Run <code>php artisan drupal:validate</code>. Most problems below show up there as a <code>FAIL</code> with a <code>Fix:</code> line. See <a href="./backend-setup#check-the-backend">Backend setup</a>. Set <code>DRUPAL_CACHE_ENABLED=false</code> while you debug, so every request reaches Drupal.</p><h2 id="symptoms" tabindex="-1">Symptoms <a class="header-anchor" href="#symptoms" aria-label="Permalink to &quot;Symptoms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th><th>Fix</th></tr></thead><tbody><tr><td>A page answers 404 for content that exists in Drupal</td><td><a href="#drupalnotfound"><code>DrupalNotFound</code></a>: anonymous users cannot read it, the alias does not resolve, or the URL prefixes disagree</td><td>Check <a href="./backend-setup#_2-allow-anonymous-reading">anonymous access</a> and the <a href="./mapping-content#_4-set-the-routes">prefixes</a></td></tr><tr><td>Every page answers 503</td><td><a href="#drupalunavailable"><code>DrupalUnavailable</code></a>: Drupal is down, slow or rate-limiting</td><td>Check <code>DRUPAL_BASE_URL</code>, timeouts and Drupal&#39;s health</td></tr><tr><td>A page answers 502</td><td><a href="#drupalbadresponse"><code>DrupalBadResponse</code></a>: a required field is missing or the answer is not JSON:API</td><td>Compare with <code>php artisan drupal:contract</code></td></tr><tr><td>The app fails at boot with a list of problems</td><td><a href="#invaliddescriptor"><code>InvalidDescriptor</code></a></td><td>Fix the listed keys</td></tr><tr><td>A view fails with &quot;has no field or relation named&quot;</td><td><a href="#unknownattribute"><code>UnknownAttribute</code></a></td><td>Use the names from the descriptor</td></tr><tr><td>Edits in Drupal do not appear</td><td>The webhook is not arriving, or the fresh window has not ended</td><td>See <a href="#content-does-not-update">Content does not update</a></td></tr><tr><td>The webhook answers 404 or 401</td><td>No secret, a clock difference, a wrong signature or a replay</td><td>See <a href="#webhook-is-refused">Webhook is refused</a></td></tr><tr><td>Related items are missing</td><td>The item shares nothing with others, the relation is not on the target type, or a request failed (look for <code>Related content fetch failed</code> in the log)</td><td>See <a href="./related-content">Related content</a></td></tr><tr><td>A tab count ends in <code>+</code></td><td>The package saw only part of the matches: a native request was cut at <code>search.native_limit</code>, or more pages follow</td><td>Narrow the search, or install the <a href="./index-extension">Index extension</a> for exact counts</td></tr><tr><td><code>/backend-docs</code> answers 404</td><td>Production, or <code>drupal-backend-docs.enabled</code> is <code>false</code></td><td>See <a href="#documentation-route-answers-404">Documentation route</a></td></tr><tr><td>Uppercase URLs answer 404</td><td><code>alias_pattern</code> accepts lowercase only</td><td>Redirect to lowercase in your app, or change the pattern</td></tr></tbody></table><h2 id="exceptions-from-drupal" tabindex="-1">Exceptions from Drupal <a class="header-anchor" href="#exceptions-from-drupal" aria-label="Permalink to &quot;Exceptions from Drupal&quot;">​</a></h2><p>All three extend <code>DrupalException</code>. Their messages are generic. The log entry carries a context with some of these keys.</p><details><summary>Context keys of a Drupal exception</summary><table tabindex="0"><thead><tr><th>Key</th><th>Meaning</th></tr></thead><tbody><tr><td><code>url</code></td><td>The request that failed</td></tr><tr><td><code>status</code></td><td>The HTTP status, or <code>null</code> when there was no answer</td></tr><tr><td><code>duration_ms</code></td><td>Time spent, including retries</td></tr><tr><td><code>attempts</code></td><td>Attempts made</td></tr><tr><td><code>error</code></td><td>The connection error message</td></tr><tr><td><code>reason</code></td><td>A short reason, such as <code>wrong resource type</code> or <code>cached miss</code></td></tr></tbody></table></details><h3 id="drupalnotfound" tabindex="-1">DrupalNotFound <a class="header-anchor" href="#drupalnotfound" aria-label="Permalink to &quot;DrupalNotFound&quot;">​</a></h3><p><strong>Status 404.</strong> Raised when:</p><ul><li>Drupal answers 404 or 403 for a request. The package treats a forbidden resource as missing.</li><li>The Decoupled Router returns no resource for the alias (<code>reason: no resource for path</code>).</li><li>The alias resolves to a different content type than the route expects (<code>reason: wrong resource type</code>).</li><li>The alias was recently unknown and is remembered (<code>reason: cached miss</code>).</li></ul><p>Fix:</p><ol><li>Open the JSON:API URL from the log in a private browser window. A 403 means anonymous users lack read permission.</li><li>Check <code>alias_prefix</code>: the package resolves <code>/{alias_prefix}/{alias}</code>, and an empty prefix resolves <code>/{alias}</code>.</li><li>If you just published the item, the unknown alias is remembered for <code>drupal.cache.negative</code> seconds. Run <code>php artisan drupal:flush</code> or wait.</li></ol><p>Laravel reports it like any exception unless your app calls <code>dontReport()</code>, as a busy site usually does.</p><h3 id="drupalunavailable" tabindex="-1">DrupalUnavailable <a class="header-anchor" href="#drupalunavailable" aria-label="Permalink to &quot;DrupalUnavailable&quot;">​</a></h3><p><strong>Status 503 with <code>Retry-After: 30</code>.</strong> Raised on a connection error or timeout, after the retries are used up, and on status 429 or 5xx.</p><p>Fix:</p><ol><li>Check that <code>DRUPAL_BASE_URL</code> is reachable from the server: <code>curl -I $DRUPAL_BASE_URL/jsonapi</code>.</li><li>If Drupal is slow, raise <code>DRUPAL_TIMEOUT</code> or the Source&#39;s <code>timeout</code>. Retries apply to connection errors and 5xx answers, up to <code>DRUPAL_RETRIES</code> extra attempts.</li><li>A 429 means Drupal or its proxy is rate-limiting you. Raise the limit there.</li></ol><p>Cached content keeps being served during an outage until the stale window ends, 24 hours by default. Only uncached requests fail.</p><h3 id="drupalbadresponse" tabindex="-1">DrupalBadResponse <a class="header-anchor" href="#drupalbadresponse" aria-label="Permalink to &quot;DrupalBadResponse&quot;">​</a></h3><p><strong>Status 502.</strong> Raised when:</p><ul><li>Drupal answers with another status such as 400.</li><li>The body is not JSON, or has no <code>data</code> array.</li><li>A <code>required</code> field is missing or empty, or a link has no <code>url</code>.</li><li>The Decoupled Router returns a path outside <code>jsonapi_path</code>.</li></ul><p>Fix: run <code>php artisan drupal:validate</code>; it names the missing field, relationship or index column. Check <code>jsonapi_path</code> if every request fails. Mark a relation <code>optional</code> to drop it instead of failing the page.</p><h2 id="errors-in-your-code" tabindex="-1">Errors in your code <a class="header-anchor" href="#errors-in-your-code" aria-label="Permalink to &quot;Errors in your code&quot;">​</a></h2><h3 id="invaliddescriptor" tabindex="-1">InvalidDescriptor <a class="header-anchor" href="#invaliddescriptor" aria-label="Permalink to &quot;InvalidDescriptor&quot;">​</a></h3><p>Raised at boot with a list of problems, or with <code>Invalid drupal-backend descriptor at [path]: reason</code> for a malformed value. A <code>schema_version</code> mismatch always stops the app. Rule violations are logged in production instead.</p><details><summary>Boot failure output</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>The drupal-backend descriptor has 2 problem(s):</span></span>
<span class="line"><span>- sources: the default source [default] is not declared.</span></span>
<span class="line"><span>- content_types.talk: ...</span></span></code></pre></div></details><p>Fix each listed key. The <a href="./descriptor-reference#what-validation-checks">Descriptor reference</a> lists the rules. An unknown key (a typo) is a warning, not a failure: <code>drupal:validate</code> prints it with a suggestion.</p><h3 id="unknownattribute" tabindex="-1">UnknownAttribute <a class="header-anchor" href="#unknownattribute" aria-label="Permalink to &quot;UnknownAttribute&quot;">​</a></h3><p>A view read <code>$talk-&gt;name</code> and the type declares no field or relation called <code>name</code>. A declared field that is empty returns <code>null</code>; only an undeclared name throws.</p><p>Fix: use the names from <code>fields</code> and <code>relations</code>, or add the field to the descriptor.</p><h3 id="other-programmer-errors" tabindex="-1">Other programmer errors <a class="header-anchor" href="#other-programmer-errors" aria-label="Permalink to &quot;Other programmer errors&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th></tr></thead><tbody><tr><td><code>Unknown content type [x].</code> / <code>Unknown source [x].</code></td><td>A key that the descriptor does not declare</td></tr><tr><td><code>Content type [x] declares no per_page.</code></td><td>A listing of a type without <code>per_page</code></td></tr><tr><td><code>Content type [x] declares no title_attribute.</code></td><td>Filter options for a type without it</td></tr><tr><td><code>Entities are immutable.</code></td><td>Setting a property on an <code>Entity</code></td></tr><tr><td><code>InvalidRelatedRequest</code></td><td>A <code>&lt;x-drupal::related&gt;</code> call the descriptor cannot serve: an unknown type or relation, relations that point to different kinds of entity, an <code>order</code> attribute a target type lacks, no criteria, a limit below 1, or more requests than <code>drupal.related.max_requests</code>. The message names the cause; it is a 500, not an empty list</td></tr></tbody></table><h2 id="content-does-not-update" tabindex="-1">Content does not update <a class="header-anchor" href="#content-does-not-update" aria-label="Permalink to &quot;Content does not update&quot;">​</a></h2><ol><li>Open the page, then <code>php artisan drupal:flush</code>, then reload. If the new content appears, the cache is the issue.</li><li>Without a webhook, content updates when the fresh window ends (<code>drupal.cache.fresh</code>, 300 seconds by default).</li><li>With a webhook, look for <code>Drupal content cache flushed by webhook</code> in the log after an edit. If it is missing, check the sender in Drupal against <a href="./webhook-and-cache-flushing">Webhook and cache flushing</a>.</li><li>If a flush works but pages stay stale, a CDN or proxy in front of the app caches them.</li></ol><h2 id="webhook-is-refused" tabindex="-1">Webhook is refused <a class="header-anchor" href="#webhook-is-refused" aria-label="Permalink to &quot;Webhook is refused&quot;">​</a></h2><p>The log line <code>Drupal webhook rejected</code> names the reason:</p><table tabindex="0"><thead><tr><th>Reason</th><th>Status</th><th>Fix</th></tr></thead><tbody><tr><td><code>secret_not_configured</code></td><td>404</td><td>Set <code>webhook.secret</code> on that Source, or check the Source name in the URL.</td></tr><tr><td><code>timestamp_invalid_or_outside_tolerance</code></td><td>401</td><td>Sync the clocks, or raise <code>webhook.tolerance</code>.</td></tr><tr><td><code>signature_mismatch</code></td><td>401</td><td>Sign the exact bytes sent with the same secret. A proxy that rewrites the body breaks it.</td></tr><tr><td><code>replayed_signature</code></td><td>401</td><td>The same signed request arrived twice, for example from a retry. Sign each attempt again with a fresh timestamp.</td></tr></tbody></table><p>A 429 means the <code>drupal-webhook</code> rate limit was exceeded.</p><h2 id="documentation-route-answers-404" tabindex="-1">Documentation route answers 404 <a class="header-anchor" href="#documentation-route-answers-404" aria-label="Permalink to &quot;Documentation route answers 404&quot;">​</a></h2><p><code>/backend-docs</code> is served outside production only, unless <code>drupal-backend-docs.enabled</code> is <code>true</code>. It is also absent when routes are cached before the package was upgraded: run <code>php artisan route:clear</code> and cache again.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Check the backend with <a href="./validation-in-ci-deploy">Validation in CI/deploy</a>.</li><li>Review the exceptions in the <a href="./vocabulary#failures">Vocabulary</a>.</li><li>Read the <a href="./caching-model">Caching model</a> to understand stale content.</li></ul>`,44)])])}const m=t(d,[["render",s]]);export{p as __pageData,m as default};
